module thermostat_controller (
    input clk,
    input resetn,
    input [7:0] set_temp,
    input [7:0] current_temp,
    output reg heating);

    parameter OFF = 0, HEATING = 1;
    reg state, next_state;

    always @(posedge clk) begin
        if (~resetn) state <= OFF;
        else state <= next_state;
    end

    always_comb begin
        case (state)
            OFF: next_state = (current_temp < set_temp) ? HEATING : OFF;
            HEATING: next_state = (current_temp >= set_temp) ? OFF : HEATING;
            default: next_state = OFF;
        endcase
    end

    always @(state) begin
        case (state)
            HEATING: heating = 1;
            default: heating = 0;
        endcase
    end
endmodule

