module top_module(
  input clk,
  input reset,
  input i,
  output reg o,
  output reg [1:0] state
);parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10;
  reg [1:0] current_state, next_state;

  always @(posedge clk) begin
    if (reset) begin
      current_state <= S0;
      o <= 1'b0;
    end
    else begin
      current_state <= next_state;
      case (current_state)
        S0: begin
          o <= 1'b0;
          if (i) begin
            next_state <= S1;
          end
          else begin
            next_state <= S0;
          end
        end
        S1: begin
          o <= 1'b0;
          if (i) begin
            next_state <= S1;
          end
          else begin
            next_state <= S2;
          end
        end
        S2: begin
          o <= 1'b1;
          if (i) begin
            next_state <= S0;
          end
          else begin
            next_state <= S0;
          end
        end
        default: begin
          o <= 1'b0;
          next_state <= S0;
        end
      endcase
    end
  end

  always @(*) begin
    state = current_state;
  end

endmodule

