module top_module(
    clk,
    data,
    ce,
    a,
    q
);parameter DATA_WIDTH = 8;  // Corrected from 32'd8 to 8
parameter ADDR_WIDTH = 1;   // Corrected from 32'd1 to 1
parameter DEPTH = 2;        // Corrected from 32'd2 to 2

input clk;
input [DATA_WIDTH-1:0] data;
input ce;
input [ADDR_WIDTH-1:0] a;
output reg [DATA_WIDTH-1:0] q;

reg [DATA_WIDTH-1:0] SRL_SIG [0:DEPTH-1];
integer i;

always @ (posedge clk)
begin
    if (ce)
    begin
        for (i = DEPTH - 1; i > 0; i = i - 1) // Changed to move from DEPTH-1 down to 1
            SRL_SIG[i] <= SRL_SIG[i-1];
        SRL_SIG[0] <= data; // The new data goes into the first position
    end
end

always @ (a or SRL_SIG[0] or SRL_SIG[1])  // Specified the array indices for sensitivity
begin
    case (a)
        1'b0: q <= SRL_SIG[0];
        1'b1: q <= SRL_SIG[1];
        default: q <= {DATA_WIDTH{1'b0}};  // Ensure q is zeroed out correctly
    endcase
end

endmodule

