description:
Design a UART receiver module that captures serial data input from a single serial line (ser_in) and converts it into an 8-bit parallel output (rx_data). The module operates based on a clock (clock) and a reset signal (reset). It utilizes a control signal (ce_16) to facilitate sampling at a 16 times rate of the data bits, while managing synchronization and timing through internal counters. As data is received, it counts the number of bits, saves the incoming data into a buffer (data_buf), and indicates when new data (new_rx_data) is available after completing the reception of 8 bits. The design is structured to ensure reliable data acquisition while handling potential synchronization issues during the serial input process.
module top_module(
	clock, reset,
	ce_16, ser_in, 
	rx_data, new_rx_data 
);

code:
module top_module(
	clock, reset,
	ce_16, ser_in, 
	rx_data, new_rx_data 
);input 			clock;			
input 			reset;			
input			ce_16;			
input			ser_in;			
output	[7:0]	rx_data;		
output 			new_rx_data;	


wire ce_1;		
wire ce_1_mid;	


reg	[7:0] rx_data;
reg	new_rx_data;
reg [1:0] in_sync;
reg rx_busy; 
reg [3:0]	count16;
reg [3:0]	bit_count;
reg [7:0]	data_buf;



always @ (posedge clock or posedge reset)
begin 
	if (reset) 
		in_sync <= 2'b11;
	else 
		in_sync <= {in_sync[0], ser_in};
end 




always @ (posedge clock or posedge reset)
begin
	if (reset) 
		count16 <= 4'b0;
	else if (ce_16) 
	begin 
		if (rx_busy | (in_sync[1] == 1'b0))
			count16 <= count16 + 4'b1;
		else 
			count16 <= 4'b0;
	end 
end 


assign ce_1 = (count16 == 4'b1111) & ce_16;

assign ce_1_mid = (count16 == 4'b0111) & ce_16;


always @ (posedge clock or posedge reset)
begin 
	if (reset)
		rx_busy <= 1'b0;
	else if (~rx_busy & ce_1_mid)
		rx_busy <= 1'b1;
	else if (rx_busy & (bit_count == 4'h8) & ce_1_mid) 
		rx_busy <= 1'b0;
end 


always @ (posedge clock or posedge reset)
begin 
	if (reset)
		bit_count <= 4'h0;
	else if (~rx_busy) 
		bit_count <= 4'h0;
	else if (rx_busy & ce_1_mid)
		bit_count <= bit_count + 4'h1;
end 


always @ (posedge clock or posedge reset)
begin 
	if (reset)
		data_buf <= 8'h0;
	else if (rx_busy & ce_1_mid)
		data_buf <= {in_sync[1], data_buf[7:1]};
end 


always @ (posedge clock or posedge reset)
begin 
	if (reset) 
	begin 
		rx_data <= 8'h0;
		new_rx_data <= 1'b0;
	end 
	else if (rx_busy & (bit_count == 4'h8) & ce_1)
	begin 
		rx_data <= data_buf;
		new_rx_data <= 1'b1;
	end 
	else 
		new_rx_data <= 1'b0;
end 

endmodule

