description:
Design a 3-bit binary counter that increments on each rising edge of the clock signal. The counter resets to zero when the reset signal is asserted. The lower two bits of the counter are outputted as a 2-bit output signal, effectively producing a 2-bit counter output.
module top_module(
  input clk,
  input reset,
  output reg [1:0] output_signal
);

code:
module top_module(
  input clk,
  input reset,
  output reg [1:0] output_signal
);reg [2:0] counter;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      counter <= 0;
      output_signal <= 0;
    end
    else begin
      counter <= counter + 1;
      output_signal <= counter[1:0];
    end
  end

endmodule

