module top_module(
    input clk,
    input rst,
    input start,
    input [31:0] target,
    input [31:0] data_in,
    input data_in_valid,
    output reg [4:0] index,  // Change to reg
    output reg done          // Change to reg
);reg [4:0] low;
reg [4:0] high;
reg [4:0] mid;
reg [31:0] mid_val;
reg found;

initial begin
    done = 0;
end

always @(posedge clk) begin
    if (rst) begin
        low <= 0;
        high <= 31;
        mid <= 15;
        found <= 0;
        index <= 0; // Reset index on reset
        done <= 0;  // Reset done on reset
    end else if (start) begin
        low <= 0;
        high <= 31;
        mid <= 15;
        found <= 0;
        index <= 0; // Reset index on start
        done <= 0;  // Reset done on start
    end else if (data_in_valid) begin
        if (data_in[mid] == target) begin
            index <= mid;
            found <= 1;
        end else if (data_in[mid] < target) begin
            low <= mid + 1;
        end else begin
            high <= mid - 1;
        end
        mid <= (low + high) / 2;
    end
    if (low >= high || found) begin
        done <= 1;
    end
end

endmodule

