description:
Implement the Verilog module based on the following description.
Module T implements the boolean function z = ~(x & y).

// Module U can be described by the following simulation waveform: 

If x = 1, y = 1, then z = 0.
If x = 0, y = 1, then z = 1.
If x = 0, y = 0, then z = 1.
If x = 1, y = 0, then z = 1.

// Now consider a top-level that uses two T submodules and two U submodules. The first input of all four submodules is connect to input 'v', and the second input of all four submodules is connected to 'w'. The output of the first T submodule is connected to a two-input AND gate, along with the output of the first U submodule. The second pair of T and U submodules is similarly connected to an OR gate. The output of the AND and the OR is connected to an XOR, whose output is 'z'.

// Implement this circuit in Verilog.

module top_module(
    input v,
    input w,
    output z);

code:
module T(
    input v,
    input w,
    output z
);
    assign z = ~(v & w);
endmodule

module U(
    input v,
    input w,
    output z
);
    assign z = ~(v & w);
endmodule

module top_module(
    input v,
    input w,
    output z
);
    wire t1_out, t2_out, u1_out, u2_out;
    wire and_out, or_out;

    T t1(.v(v), .w(w), .z(t1_out));
    T t2(.v(v), .w(w), .z(t2_out));
    U u1(.v(v), .w(w), .z(u1_out));
    U u2(.v(v), .w(w), .z(u2_out));

    assign and_out = t1_out & u1_out;
    assign or_out = t2_out | u2_out;

    assign z = and_out ^ or_out;
endmodule

