  input clk,
  output reg pulse
);reg [4:0] counter = 0;

  always @(posedge clk) begin
    if (counter == 5'b10000) begin // Changed to 5 bits
      counter <= 0;
      pulse <= 1;
    end else begin
      counter <= counter + 1;
      pulse <= (counter == 5'b01111) ? 0 : pulse;  // Correct the pulse assignment at the right time
    end
  end

endmodule

