description:
Design a clock divider circuit that generates a lower frequency clock output (clk_o) from a higher frequency input clock (clk_i). The circuit utilizes a 28-bit counter (cnt) that increments on each rising edge of clk_i, resetting to zero when a reset signal (rst_n_i) is asserted. The output clock (clk_o) is active when the counter has not reached a specific threshold, effectively dividing the incoming clock frequency. When the reset signal is low, the circuit operates normally; when high, it resets the counter. This design is useful for applications requiring slower clock signals derived from a faster one.
module top_module(
    input rst_n_i,
    input clk_i,
    output clk_o
    );

code:
module top_module(
    input rst_n_i,
    input clk_i,
    output clk_o
    );reg [27:0] cnt;

    wire rst = !rst_n_i;
    always @(posedge clk_i or posedge rst) begin
        if (rst == 1'b1)
            cnt <= 'h0;
        else

            cnt <= (cnt >= 'h5F5E100) ? 'h0 : cnt + 'h1;
    end


    wire clk_div = rst_n_i & (cnt < 'h2FAF080);

    assign clk_o = clk_div;


endmodule

