description:
Design a key debounce circuit. The module takes a debounced clock signal and a key input, producing a single pulse output when the key transitions from low to high. It utilizes two flip-flops to filter out noise and ensure that only a clean pulse is generated for each valid key press.
module top_module(
    input debounce_clk,
    input key,
    output key_pulse
);

code:
module top_module(
    input debounce_clk,
    input key,
    output key_pulse
);reg Q1 = 1'b0;
    reg Q2 = 1'b0;


    always @ (posedge debounce_clk) begin
        Q1 <= key;
        Q2 <= Q1;
    end

    assign key_pulse = Q1 & ~Q2;

endmodule

