module top_module(
	input reset_n,
	input DelayClk,				
	input DelayEnable,
	input [15:0] DelayTime,
	output reg DelayDone
);reg [16:0] CountReg;

always @(negedge reset_n or posedge DelayClk or negedge DelayEnable)
begin
	if(!reset_n)
	begin
		CountReg <= 0;
		DelayDone <= 0;
	end
	else if(!DelayEnable)
	begin
		CountReg <= 0;
		DelayDone <= 0;
	end
	else 
	begin
		if(CountReg>DelayTime)
		begin
			CountReg <= 0;
			DelayDone <= 1;
		end
		else
		begin
			CountReg <= CountReg + 1'b1;
			DelayDone <= 0;
		end	
	end
end

endmodule

