module thermostat (
	input clk,
	input resetn,
	input [7:0] temperature,
	input [7:0] low_thresh,
	input [7:0] high_thresh,
	output heat,
	output cool);

	parameter IDLE=0, HEATING=1, COOLING=2;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			IDLE: begin
				if (temperature < low_thresh) next_state = HEATING;
				else if (temperature > high_thresh) next_state = COOLING;
				else next_state = IDLE;
			end
			HEATING: next_state = (temperature >= low_thresh) ? IDLE : HEATING;
			COOLING: next_state = (temperature <= high_thresh) ? IDLE : COOLING;
			default: next_state = IDLE;
		endcase
	end

	assign heat = (state == HEATING);
	assign cool = (state == COOLING);
endmodule

