module top_module_tb;

    // Testbench signals (sequential circuit)
    reg [3:0] addr_r;
    reg [3:0] addr_w;
    reg [7:0] data_in;
    reg rd_en;
    reg wr_en;
    wire [7:0] data_out;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .addr_r(addr_r),
        .addr_w(addr_w),
        .data_in(data_in),
        .rd_en(rd_en),
        .wr_en(wr_en),
        .data_out(data_out)
    );

    // Clock generation (10ns period)
    initial begin
        rd_en = 0;
        forever #5 rd_en = ~rd_en;
    end

        task reset_dut;

        begin
            wr_en = 0;
            addr_w = 0;
            addr_r = 0;
            data_in = 0;
            #20;
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Basic Write/Read", test_num);
            reset_dut();


            addr_w = 4'h1;
            data_in = 8'hA5;
            #10;
            wr_en = 1;
            #10;
            wr_en = 0;


            addr_r = 4'h1;
            @(posedge rd_en);
            #2;
            #1;

            check_outputs(8'hA5);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Boundary Address (Max)", test_num);
            reset_dut();


            addr_w = 4'hF;
            data_in = 8'h5A;
            #10;
            wr_en = 1;
            #10;
            wr_en = 0;

            addr_r = 4'hF;
            @(posedge rd_en);
            #2;
            #1;

            check_outputs(8'h5A);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Address Isolation", test_num);
            reset_dut();


            addr_w = 4'h2; data_in = 8'h11;
            #10; wr_en = 1; #10; wr_en = 0;


