description:
Design a 4-bit binary counter with synchronous reset functionality. The counter increments its value on each rising edge of the clock (clk) signal, and if the reset signal (reset_n) is asserted low, it resets the count to zero. The current count value is output as a 4-bit wide output (count).
module top_module(
    input clk,
    input reset_n,
    output [3:0] count
);

code:
module top_module(
    input clk,
    input reset_n,
    output [3:0] count
);reg [3:0] count_reg;

    always @(posedge clk) begin
        if (!reset_n) begin
            count_reg <= 4'b0;
        end else begin
            count_reg <= count_reg + 1;
        end
    end

    assign count = count_reg;

endmodule

