 input rst; 
 input [2:0] as1; 
 input [2:0] bs1; 
 input [2:0] cs1; 
 input cw1; 
 input [15:0] cd1; 
 output [15:0] AD1; 
 output [15:0] BD1; 
 output [15:0] CD1; 
 output WT1; 
 input [2:0] as2; 
 input [2:0] bs2; 
 input [2:0] cs2; 
