 assign AD2=rDat[as2]; 
 assign BD1=rDat[bs1]; 
 assign BD2=rDat[bs2]; 
 assign CD1=rDat[cs1]; 
 assign CD2=rDat[cs2]; 
 assign WT1=(cs1==cs2)&&cw2; 
