        shift_reg <= 32'b0;
        serial_out <= 1'b0;
    end else if (load) begin
        shift_reg <= parallel_in;
        serial_out <= parallel_in[0];
    end else if (shift) begin
        serial_out <= shift_reg[0];
        shift_reg <= {1'b0, shift_reg[31:1]};
    end
end

endmodule

